INSERT INTO "message_templates" ("id", "trigger", "titleAr", "titleEn", "bodyAr", "bodyEn") VALUES ('tmpl-01', 'order_ready', 'إشعار جاهزية القالب أو السماعة', 'Order Ready Notification', 'مرحباً عزيزنا العميل {client_name}، نود إبلاغكم بأن طلبكم رقم ({order_no}) الخاص بالقالب/السماعة الطبية أصبح جاهزاً للاستلام والتجربة في {branch}. نتشرف بزيارتكم.', 'Dear {client_name}, your custom earmold/hearing aid order ({order_no}) is now ready for pickup and fitting at {branch}. We look forward to your visit.') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "message_templates" ("id", "trigger", "titleAr", "titleEn", "bodyAr", "bodyEn") VALUES ('tmpl-02', 'invoice_receipt', 'نسخة الفاتورة الإلكترونية', 'Invoice & Receipt Copy', 'شكراً لثقتكم بنا، عزيزنا {client_name}. تم إصدار فاتورتكم رقم ({invoice_no}) بمبلغ إجمالي {grand_total} ر.س والمتبقي {remaining_due} ر.س. نتمنى لكم دوام الصحة والعافية.', 'Thank you for choosing us, {client_name}. Your invoice ({invoice_no}) has been generated for {grand_total} SAR. Remaining balance: {remaining_due} SAR.') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "message_templates" ("id", "trigger", "titleAr", "titleEn", "bodyAr", "bodyEn") VALUES ('tmpl-03', 'appointment', 'تذكير بموعد الفحص أو البرمجة', 'Fitting Appointment Reminder', 'نذكركم بموعدكم القادم لجلسة فحص السمع وبرمجة السماعة يوم {date} في {branch} مع الأخصائي المعالج. يرجى تأكيد الحضور.', 'Reminder of your upcoming audiology / fitting appointment on {date} at {branch}. Please confirm your attendance.') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "message_templates" ("id", "trigger", "titleAr", "titleEn", "bodyAr", "bodyEn") VALUES ('tmpl-04', 'battery_reminder', 'تذكير بطاريات وصيانة وقائية', 'Battery & Maintenance Reminder', 'عزيزنا {client_name}، حفاظاً على كفاءة سماعتكم الطبية، يسعدنا تذكيركم بمرور 6 أشهر على استلام السماعة لعمل فحص دوري مجاني واستلام حزمة بطاريات وفلاتر جديدة من أقرب فرع.', 'Dear {client_name}, to keep your hearing aid performing at its best, you are invited for a complimentary periodic checkup and maintenance at {branch}.') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "message_logs" ("id", "clientId", "clientName", "phone", "channel", "trigger", "content", "status", "sentAt") VALUES ('msg-01', 'cl-01', 'محمد بن سلطان القحطاني', '0505123456', 'whatsapp', 'invoice_receipt', 'شكراً لثقتكم بنا، عزيزنا محمد بن سلطان القحطاني. تم إصدار فاتورتكم رقم (INV-2026-0089) بمبلغ إجمالي 14386.5 ر.س والمتبقي 0 ر.س.', 'delivered', '2026-09-15 16:35') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "message_logs" ("id", "clientId", "clientName", "phone", "channel", "trigger", "content", "status", "sentAt") VALUES ('msg-02', 'cl-03', 'عبدالله بن فهد الغامدي', '0567123987', 'whatsapp', 'order_ready', 'مرحباً عزيزنا العميل عبدالله بن فهد الغامدي، نود إبلاغكم بأن طلبكم رقم (EMO-2026-0042) الخاص بالقالب أصبح جاهزاً للاستلام.', 'sent', '2026-09-16 11:20') ON CONFLICT ("id") DO NOTHING;
